    u_4} : {C : Type u_2} →
  {D : Type u_4} →
    [inst : CategoryTheory.Category.{u_1, u_2} C] →
      [inst_1 : CategoryTheory.Category.{u_3, u_4} D] →
        {F : @CategoryTheory.Functor.{u_1, u_3, u_2, u_4} C inst D inst_1} →
          {G G' : @CategoryTheory.Functor.{u_3, u_1, u_4, u_2} D inst_1 C inst} →
            @CategoryTheory.Adjunction.{u_1, u_3, u_2, u_4} C inst D inst_1 F G →
              @CategoryTheory.Adjunction.{u_1, u_3, u_2, u_4} C inst D inst_1 F G' →
                @CategoryTheory.Iso.{max u_4 u_1, max (max (max u_2 u_4) u_1) u_3}
                  (@CategoryTheory.Functor.{u_3, u_1, u_4, u_2} D inst_1 C inst)
                  (@CategoryTheory.Functor.category.{u_3, u_1, u_4, u_2} D inst_1 C inst) G G'

